'use strict';
// The two visible windows are observed. Their sensor mapping and calibration are unknown.
const cameraDefaults={yaw:25,down:0,z:150,inset:20,spacing:130,hfov:100,vfov:60,far:1500,recess:6,windowW:116,windowH:52,brackets:true,rays:true};
let cameraDesign={...cameraDefaults};
const camDot=(a,b)=>a.reduce((s,v,i)=>s+v*b[i],0);
function cameraFrames(){const c=cameraDesign;return [1,-1].map(side=>{const origin=[params.L/2-c.inset,side*c.spacing,c.z],rotation=mMul(mRot('z',side*c.yaw),mRot('y',c.down)),matrix=mMul(mTrans(...origin),rotation);return{side,origin,matrix,forward:mVector(rotation,[1,0,0]),horizontal:mVector(rotation,[0,1,0]),vertical:mVector(rotation,[0,0,1]),yaw:side*c.yaw,down:c.down};});}
function cameraCoordinates(){return{positions:cameraFrames().map(f=>f.origin),size:`광학창 2곳 / 요 ±${cameraDesign.yaw}° / 하향 ${cameraDesign.down}° (검토값)`,desc:'등가 광학 중심 / 실제 내·외부 보정 미확인'};}
function cameraRay(f,h,v){const a=Math.tan(h*Math.PI/180),b=Math.tan(v*Math.PI/180),d=f.forward.map((n,i)=>n+a*f.horizontal[i]+b*f.vertical[i]),norm=Math.hypot(...d);return d.map(n=>n/norm);}
function cameraGroundHit(origin,direction){if(direction[2]>=-1e-10)return null;const t=-origin[2]/direction[2];return origin.map((v,i)=>v+t*direction[i]);}
// Convex clipping on z=0; depth is measured along the optical axis, not radial range.
function cameraClip(poly,normal,constant){if(!poly.length)return[];const out=[],value=p=>camDot(normal,[p[0],p[1],0])+constant;for(let i=0;i<poly.length;i++){const a=poly[i],b=poly[(i+1)%poly.length],va=value(a),vb=value(b),insideA=va>=-1e-8,insideB=vb>=-1e-8;if(insideA)out.push(a);if(insideA!==insideB){const t=va/(va-vb);out.push(a.map((v,j)=>v+t*(b[j]-v)));}}return out;}
function cameraGroundPolygon(f){const h=cameraDesign,th=Math.tan(h.hfov*Math.PI/360),tv=Math.tan(h.vfov*Math.PI/360),extent=h.far*12+params.L+params.W;let poly=[[-extent,-extent],[extent,-extent],[extent,extent],[-extent,extent]];const constraints=[{n:f.forward,b:-50},{n:f.forward.map(v=>-v),b:h.far}];for(const [axis,t]of[[f.horizontal,th],[f.vertical,tv]])for(const sign of[-1,1])constraints.push({n:f.forward.map((v,i)=>t*v+sign*axis[i]),b:0});for(const q of constraints)poly=cameraClip(poly,q.n,q.b-camDot(q.n,f.origin));return poly;}
function cameraPointVisible(f,p){const d=p.map((v,i)=>v-f.origin[i]),x=camDot(d,f.forward);return x>=50-1e-7&&x<=cameraDesign.far+1e-7&&Math.abs(camDot(d,f.horizontal))<=x*Math.tan(cameraDesign.hfov*Math.PI/360)+1e-7&&Math.abs(camDot(d,f.vertical))<=x*Math.tan(cameraDesign.vfov*Math.PI/360)+1e-7;}
function cameraWindowMargins(){const c=cameraDesign;return{horizontal:c.windowW/2-38-c.recess*Math.tan(c.hfov*Math.PI/360),vertical:c.windowH/2-8-c.recess*Math.tan(c.vfov*Math.PI/360)};}
function cameraOBB(matrix,center,size,name){const vertices=[];for(const x of[-1,1])for(const y of[-1,1])for(const z of[-1,1])vertices.push(mPoint(matrix,center.map((n,i)=>n+[x,y,z][i]*size[i]/2)));return{vertices,axes:[[1,0,0],[0,1,0],[0,0,1]].map(v=>mVector(matrix,v)),name};}
function cameraOBBGap(a,b){const cross=(u,v)=>[u[1]*v[2]-u[2]*v[1],u[2]*v[0]-u[0]*v[2],u[0]*v[1]-u[1]*v[0]],axes=[...a.axes,...b.axes,...a.axes.flatMap(u=>b.axes.map(v=>cross(u,v)))].filter(v=>Math.hypot(...v)>1e-8);return Math.max(...axes.map(v=>{const n=Math.hypot(...v),axis=v.map(x=>x/n),A=a.vertices.map(p=>camDot(p,axis)),B=b.vertices.map(p=>camDot(p,axis));return Math.max(Math.min(...A)-Math.max(...B),Math.min(...B)-Math.max(...A));}));}
function cameraMountOBBs(f){
 const h=cameraDesign,fixed=mMul(mTrans(...f.origin),mRot('z',f.yaw)),top=197-h.z,parts=[cameraOBB(f.matrix,[-20,0,0],[36,90,38],'본체')];
 {parts.push(cameraOBB(fixed,[-40,0,187-h.z],[64,114,12],'프레임 어댑터'),cameraOBB(fixed,[-40,0,top-2],[64,114,4],'고정판'));for(const s of[-1,1])parts.push(cameraOBB(fixed,[-12,s*50,(top-4)/2],[84,4,top+8],'피치 지지 귀'));}
 return parts;
}
function cameraPackaging(){const cx=params.L/2-70,cy=params.W/2-80,h=cameraDesign;return cameraFrames().map(f=>{
 const parts=cameraMountOBBs(f);
 const caster=[];for(const s of[-1,1])caster.push(cameraOBB(mIdentity(),[cx+s*34,f.side*cy,149],[12,62,78],'캐스터 가이드'));
 caster.push(cameraOBB(mIdentity(),[cx,f.side*cy,145],[50,50,72],'코일 외형'),cameraOBB(mIdentity(),[cx,f.side*cy,178],[58,58,16],'검은 캡'),cameraOBB(mIdentity(),[cx,f.side*cy,185],[66,66,8],'상단 플랜지'));
 const pairs=parts.flatMap(a=>caster.map(b=>({part:a.name,against:b.name,gap:cameraOBBGap(a,b)}))),closest=pairs.reduce((a,b)=>a.gap<b.gap?a:b);
 return{side:f.side,...closest,interference:pairs.some(p=>p.gap<0),required:3,clear:pairs.every(p=>p.gap>=3)};
 });}
function cameraAnalysis(){const frames=cameraFrames(),margins=cameraWindowMargins(),rows=frames.map(f=>{const bottom=cameraGroundHit(f.origin,cameraRay(f,0,-cameraDesign.vfov/2)),axis=cameraGroundHit(f.origin,f.forward),poly=cameraGroundPolygon(f);return{side:f.side,origin:f.origin,forward:f.forward,yaw:f.yaw,down:f.down,bottomGround:bottom,axisGround:axis,groundPolygon:poly,nearGround:bottom?Math.hypot(bottom[0]-f.origin[0],bottom[1]-f.origin[1]):null};});let common=rows[0].groundPolygon;for(const p of [frames[1]]){const th=Math.tan(cameraDesign.hfov*Math.PI/360),tv=Math.tan(cameraDesign.vfov*Math.PI/360),planes=[{n:p.forward,b:-50},{n:p.forward.map(v=>-v),b:cameraDesign.far}];for(const [axis,t]of[[p.horizontal,th],[p.vertical,tv]])for(const s of[-1,1])planes.push({n:p.forward.map((v,i)=>t*v+s*axis[i]),b:0});for(const q of planes)common=cameraClip(common,q.n,q.b-camDot(q.n,p.origin));}
 const area=poly=>Math.abs(poly.reduce((s,p,i)=>{const q=poly[(i+1)%poly.length];return s+p[0]*q[1]-p[1]*q[0];},0))/2;
 const points=Array.from({length:101},(_,i)=>[params.L/2+i*25,0,0]),first=points.find(p=>frames.some(f=>cameraPointVisible(f,p))),both=points.find(p=>frames.every(f=>cameraPointVisible(f,p)));
 return{rows,commonGround:common,commonArea:area(common),margins,packaging:cameraPackaging(),centerlineFirst:first?first[0]-params.L/2:null,centerlineBoth:both?both[0]-params.L/2:null,centerlineSampleStep:25,occlusionIncluded:false};}
function cameraExport(){return{design:{...cameraDesign},frames:cameraFrames(),analysis:cameraAnalysis(),frameConvention:'base +X forward, +Y left, +Z up; camera local +X optical, +Y horizontal-left, +Z image-up; Rz(side*yaw) Ry(down)',status:'two exterior windows observed; ±25° yaw and 0° tilt are candidate review values, not calibrated extrinsics; one mobile stereo system listed by manufacturer; mapping to exterior windows unknown',interfaces:{body_xyz_mm:[36,90,38],base_plate_xyz_mm:[64,114,4],frame_adapter_xyz_mm:[64,114,12],pitch_trunnion_diameter_mm:8,fasteners:'4 x M4 frame attachment per bracket; proposed',window_mm:[116,52],aperture_centers_local_y_mm:[-30,30],aperture_radius_mm:8,cable_radius_mm:25},sources:['https://public.hday.io/site/robots/friday.webp','https://public.hday.io/site/hero/product.mp4','https://holiday-robotics.com/privacy-robot']};}
